insert into private.condition_profiles (slug, name, primary_clerkship, clerkships, organ_systems, validation, review, profile) values ($rounds_kb$alcohol-use-disorder-aud$rounds_kb$, $rounds_kb$Alcohol Use Disorder (AUD)$rounds_kb$, $rounds_kb$psychiatry$rounds_kb$, array[$rounds_kb$psychiatry$rounds_kb$, $rounds_kb$internalMedicine$rounds_kb$, $rounds_kb$familyMedicine$rounds_kb$, $rounds_kb$emergency$rounds_kb$]::text[], array[$rounds_kb$behavioral$rounds_kb$]::text[], $rounds_kb$passed$rounds_kb$, $rounds_kb$pending$rounds_kb$, $rounds_kb${"schema_version": "0.2", "slug": "alcohol-use-disorder-aud", "triage": {"name": "Alcohol Use Disorder (AUD)", "case_suitable": true, "reason": "Diagnosis made by history of impaired control, craving, tolerance and withdrawal; common and high-yield for interview skills.", "kind": "disease", "category": "substance use disorder", "organ_systems": ["behavioral"], "primary_clerkship": "psychiatry", "secondary_clerkships": ["internalMedicine", "familyMedicine", "emergency"], "commonness": "very_common", "settings": ["clinic", "inpatient", "emergency", "psychiatric"], "is_cancer": false}, "generation": {"stages": [{"stage": "triage", "model": "deepseek/deepseek-chat", "prompt_version": "7", "generated_at": "2026-10-05T04:15:33Z"}, {"stage": "patient_presentation", "model": "deepseek/deepseek-chat", "prompt_version": "7", "generated_at": "2026-10-05T04:23:40Z"}, {"stage": "exam_vitals", "model": "deepseek/deepseek-chat", "prompt_version": "7", "generated_at": "2026-10-05T04:23:48Z"}, {"stage": "diagnostics", "model": "deepseek/deepseek-chat", "prompt_version": "7", "generated_at": "2026-10-05T04:24:17Z"}, {"stage": "differential_course", "model": "deepseek/deepseek-chat", "prompt_version": "7", "generated_at": "2026-10-05T04:24:30Z"}, {"stage": "teaching", "model": "deepseek/deepseek-chat", "prompt_version": "7", "generated_at": "2026-10-05T04:24:37Z"}], "validation": {"status": "passed", "rule_errors": [], "review_issues": ["auto-repa