peak": "20s–40s", "possible_min": 12, "possible_max": 90}, "sex": "male_predominant", "demographics": ["Men are roughly twice as likely as women to meet criteria for AUD", "Prevalence is highest in adults under 40 and declines somewhat with age", "Higher rates are reported in some American Indian/Alaska Native and White populations and in people with lower income or less education", "Sexual and gender minority adults report higher rates of heavy drinking"], "risk_factors": [{"text": "Family history of AUD in a first-degree relative", "strength": "strong"}, {"text": "Drinking before age 15", "strength": "strong"}, {"text": "Binge drinking (5 or more drinks for men, 4 or more for women in about 2 hours)", "strength": "strong"}, {"text": "Male sex", "strength": "moderate"}, {"text": "Depression, anxiety, PTSD or another psychiatric condition", "strength": "moderate"}, {"text": "Childhood trauma or adverse childhood experiences", "strength": "moderate"}, {"text": "Easy access to alcohol, peer or workplace drinking culture", "strength": "moderate"}, {"text": "Tobacco or other substance use", "strength": "moderate"}, {"text": "Chronic pain or chronic illness", "strength": "weak"}], "comorbidities": ["Major depressive disorder", "Generalized anxiety disorder", "Post-traumatic stress disorder", "Bipolar disorder", "Tobacco use disorder", "Cannabis or opioid use disorder", "Alcohol-associated liver disease", "Pancreatitis", "Hypertension", "Insomnia", "Peripheral neuropathy"], "family_history": ["Alcohol use disorder in a parent or sibling", "Depression or anxiety in the family", "Other substance use disorder in the family"], "social_history": ["Drinks most days or in heavy weekend binges", "Has driven after drinking or had other alcohol-related injuries", "Missed work or school because of drinking or hangovers", "Relationship conflict about drinking", "Lives alone or has limited social support", "Financial or legal problems related to drinking"], "exposures": ["Work or social settings where heavy drinking is normal", "Easy access to cheap alcohol"], "risk_medications": ["benzodiazepines", "opioids", "sedative-hypnotics"]}, "presentation": {"chief_complaints": [{"text": "I drink more than I should and I can't seem to cut back", "frequency": "common"}, {"text": "My family keeps telling me my drinking is a problem", "frequency": "common"}, {"text": "I wake up shaky and sweaty and need a drink to steady myself", "frequency": "sometimes"}, {"text": "I've been feeling down and anxious and drinking to cope", "frequency": "sometimes"}, {"text": "I blacked out again last weekend", "frequency": "sometimes"}, {"text": "My stomach hurts and I've been throwing up", "frequency": "sometimes"}], "hpi": {"onset": "Usually gradual over years, often starting with regular drinking in the late teens or twenties and escalating after a stressor, loss, or new social setting", "duration": "Typically years; the pattern of heavy drinking usually has been present for at least 12 months before criteria are met", "progression": "Drinking amounts and frequency creep upward, tolerance develops, and the person starts to lose control over how much they drink; attempts to stop bring withdrawal symptoms and repeated relapses", "location": "Not applicable", "radiation": "Not applicable", "quality": "A pattern of drinking more than intended, strong urges to drink, and time spent drinking or recovering", "severity": "Ranges from mild (a few criteria) to severe with daily drinking, blackouts, withdrawal, and medical complications", "timing": "Often daily or near-daily; some people binge on weekends or in episodes lasting days", "aggravating": ["Stress", "Relationship conflict", "Being around other people who drink", "Depression or anxiety", "Payday or having extra money"], "relieving": ["Drinking more alcohol", "Brief periods of abstinence, often followed by relapse"], "associated_symptoms": [{"text": "Drinking more or longer than planned", "frequency": "almost_always"}, {"text": "Strong craving or urge to drink", "frequency": "common"}, {"text": "Needing more alcohol to get the same effect (tolerance)", "frequency": "common"}, {"text": "Shakiness, sweating, nausea or trouble sleeping when not drinking (withdrawal)", "frequency": "common"}, {"text": "Blackouts or memory gaps after drinking", "frequency": "common"}, {"text": "Spending less time on hobbies, work or family because of drinking", "frequency": "common"}, {"text": "Continued drinking despite knowing it is harming health, mood or relationships", "frequency": "common"}, {"text": "Morning drinking or drinking to relieve withdrawal", "frequency": "sometimes"}, {"text": "Drinking while driving or in other risky situations", "frequency": "sometimes"}, {"text": "Failed attempts to cut down or quit", "frequency": "common"}, {"text": "Irritability, anxiety or low mood between drinks", "frequency": "common"}, {"text": "Vomiting blood or black stools", "frequency": "rare"}, {"text": "Seizures during withdrawal", "frequency": "rare"}, {"text": "Seeing or hearing things that are not there during withdrawal", "frequency": "rare"}], "pertinent_negatives": ["No history of drinking in the morning every day from the start (early morning drinking suggests more severe dependence)", "No use of intravenous drugs", "No history of mania or psychosis unrelated to alcohol", "No recent head injury", "No intentional overdose", "No abdominal pain radiating to the back with vomiting (would suggest pancreatitis)", "No fever or productive cough"]}, "ros": [{"system": "constitutional", "positives": [{"text": "Fatigue", "frequency": "common"}, {"text": "Poor appetite", "frequency": "sometimes"}, {"text": "Weight loss", "frequency": "sometimes"}, {"text": "Night sweats", "frequency": "sometimes"}], "negatives": ["High fever", "Chills"]}, {"system": "psychiatric", "positives": [{"text": "Anxiety or irritability when not drinking", "frequency": "common"}, {"text": "Depressed mood", "frequency": "common"}, {"text": "Trouble sleeping", "frequency": "common"}, {"text": "Guilt or shame about drinking", "frequency": "common"}, {"text": "Thoughts of harming oneself", "frequency": "sometimes"}], "negatives": ["Auditory hallucinations while sober", "Delusions", "Mania"], "argues_against": ["Psychosis or mania independent of alcohol use"]}, {"system": "gastrointestinal", "positives": [{"text": "Nausea or vomiting in the morning", "frequency": "common"}, {"text": "Heartburn or stomach pain", "frequency": "sometimes"}, {"text": "Diarrhea", "frequency": "sometimes"}, {"text": "Vomiting blood or black stools", "frequency": "rare"}], "negatives": ["Bloody diarrhea", "Severe right upper quadrant pain with fever"], "argues_against": ["Acute cholecystitis", "Infectious gastroenteritis"]}, {"system": "neurologic", "positives": [{"text": "Tremor of the hands", "frequency": "common"}, {"text": "Memory gaps or blackouts", "frequency": "common"}, {"text": "Numbness or tingling in the feet", "frequency": "sometimes"}, {"text": "Seizures during withdrawal", "frequency": "rare"}], "negatives": ["Focal weakness", "Slurred speech when sober", "Severe headache"], "argues_against": ["Stroke", "Intracranial hemorrhage"]}, {"system": "cardiovascular", "positives": [{"text": "Palpitations", "frequency": "sometimes"}, {"text": "Elevated blood pressure readings", "frequency": "sometimes"}], "negatives": ["Chest pain at rest", "Leg swelling"], "argues_against": ["Acute coronary syndrome", "Heart failure"]}, {"system": "musculoskeletal", "positives": [{"text": "Muscle cramps", "frequency": "sometimes"}], "negatives": ["Joint swelling", "Muscle weakness"]}, {"system": "skin", "positives": [{"text": "Easy bruising", "frequency": "sometimes"}, {"text": "Yellowing of the eyes or skin", "frequency": "rare"}, {"text": "Itching", "frequency": "rare"}], "negatives": ["Rash", "Spider veins on the chest and face"]}, {"system": "reproductive", "positives": [{"text": "Decreased sex drive", "frequency": "sometimes"}, {"text": "Erectile dysfunction", "frequency": "sometimes"}], "negatives": ["Testicular pain", "Vaginal bleeding"]}], "atypical": [{"population": "older_adults", "how_it_differs": "They often drink less overall but still meet criteria; they may present with falls, confusion, insomnia, or worsening heart failure rather than obvious intoxication, and they reach higher blood alcohol levels with smaller amounts.", "missing_classic_features": ["Heavy daily drinking", "Young age at first drink"]}, {"population": "pregnancy", "how_it_differs": "Patients often minimize or hide drinking because of stigma; they may present for prenatal care with poor weight gain, preterm contractions, or fetal growth concerns rather than asking for help with alcohol.", "missing_classic_features": ["Willingness to discuss drinking openly", "Classic withdrawal complaints"]}, {"population": "children", "how_it_differs": "Adolescents usually binge drink episodically rather than drink daily; they present with school problems, injuries, or mood changes, and withdrawal is uncommon.", "missing_classic_features": ["Daily drinking", "Withdrawal symptoms", "Medical complications of chronic use"]}, {"population": "hepatic_impairment", "how_it_differs": "Patients with cirrhosis may report much lower intake because they feel intoxicated quickly, and they can present with confusion, bleeding, or abdominal swelling rather than craving.", "missing_classic_features": ["High reported tolerance", "Heavy drinking without immediate effects"]}]}, "exam": {"general": {"mild": "Well-appearing, alert, no distress; may smell of alcohol or have mild tremor", "moderate": "Restless, mildly tremulous, diaphoretic, appears anxious or irritable", "severe": "Ill-appearing, visibly shaking, sweating, agitated or drowsy; may be disoriented", "critical": "Toxic or obtunded, unresponsive to voice, or actively seizing; may be hypotensive and tachycardic"}, "findings": [{"id": "hand-tremor", "region": "extremities", "maneuver": "Ask t