insert into private.condition_profiles (slug, name, primary_clerkship, clerkships, organ_systems, validation, review, profile) values ($rounds_kb$angina$rounds_kb$, $rounds_kb$Angina$rounds_kb$, $rounds_kb$internalMedicine$rounds_kb$, array[$rounds_kb$internalMedicine$rounds_kb$, $rounds_kb$emergency$rounds_kb$, $rounds_kb$familyMedicine$rounds_kb$]::text[], array[$rounds_kb$cardiovascular$rounds_kb$]::text[], $rounds_kb$passed$rounds_kb$, $rounds_kb$pending$rounds_kb$, $rounds_kb${"schema_version": "0.2", "slug": "angina", "triage": {"name": "Angina", "case_suitable": true, "reason": "Chest pain is a classic undifferentiated symptom case; history, ECG, and troponin lead to stable angina versus ACS and its mimics.", "kind": "symptom", "category": "coronary ischemia", "organ_systems": ["cardiovascular"], "primary_clerkship": "internalMedicine", "secondary_clerkships": ["emergency", "familyMedicine"], "commonness": "very_common", "settings": ["clinic", "emergency", "inpatient"], "is_cancer": false}, "generation": {"stages": [{"stage": "triage", "model": "deepseek/deepseek-chat", "prompt_version": "7", "generated_at": "2026-10-05T04:15:42Z"}, {"stage": "patient_presentation", "model": "deepseek/deepseek-chat", "prompt_version": "7", "generated_at": "2026-10-05T04:25:42Z"}, {"stage": "exam_vitals", "model": "deepseek/deepseek-chat", "prompt_version": "7", "generated_at": "2026-10-05T04:25:48Z"}, {"stage": "diagnostics", "model": "deepseek/deepseek-chat", "prompt_version": "7", "generated_at": "2026-10-05T04:26:12Z"}, {"stage": "differential_course", "model": "deepseek/deepseek-chat", "prompt_version": "7", "generated_at": "2026-10-05T04:26:20Z"}, {"stage": "teaching", "model": "deepseek/deepseek-chat", "prompt_version": "7", "generated_at": "2026-10-05T04:26:27Z"}], "validation": {"status": "passed", "rule_errors": [], "review_issues": ["auto-repaired: workup: renamed 'ecg' to 'ECG'", "auto-repaired: workup: 'chest x-ray' was in ['initial', 'supporting', 'not_indicated'