ate"}, {"text": "Physical inactivity", "strength": "moderate"}, {"text": "Chronic kidney disease", "strength": "moderate"}, {"text": "Male sex", "strength": "weak"}, {"text": "Chronic stress or depression", "strength": "weak"}], "comorbidities": ["Hypertension", "Type 2 diabetes", "Hyperlipidemia", "Prior myocardial infarction", "Heart failure", "Chronic kidney disease", "Peripheral arterial disease", "Obstructive sleep apnea"], "family_history": ["Heart attack or coronary bypass in a father or brother before age 55", "Heart attack or coronary bypass in a mother or sister before age 65", "Sudden cardiac death in a close relative", "Familial high cholesterol"], "social_history": ["Current or former smoking", "Sedentary desk job", "High-stress work or caregiving role", "Heavy alcohol use", "Lives in a neighborhood with limited access to fresh food or safe walking areas"], "exposures": ["Long-term secondhand tobacco smoke", "Cold weather", "Air pollution on high-smog days"], "risk_medications": ["Cocaine", "Amphetamines", "Sumatriptan", "Ergotamine", "Rofecoxib", "Testosterone"]}, "presentation": {"chief_complaints": [{"text": "My chest feels tight and heavy when I walk up the stairs", "frequency": "almost_always"}, {"text": "It feels like someone is standing on my chest", "frequency": "common"}, {"text": "I get a pressure in my chest that goes away when I sit down", "frequency": "common"}, {"text": "My chest hurts and the pain runs down my left arm", "frequency": "sometimes"}, {"text": "It feels like bad indigestion when I exert myself", "frequency": "sometimes"}], "hpi": {"onset": "Gradual over weeks to months; the pattern becomes predictable", "duration": "Each episode lasts about 2 to 10 minutes and resolves within minutes of stopping the activity", "progression": "Started with heavy exertion only, then began coming on with lighter activity such as one flight of stairs or walking uphill; frequency and ease of triggering have slowly increased", "location": "Mid-chest, behind the breastbone; may be described as the whole front of the chest", "radiation": "Often to the left shoulder and inner left arm; sometimes to the neck, jaw, back, or upper abdomen", "quality": "Pressure, squeezing, tightness, heaviness, or a band-like ache; rarely sharp or stabbing", "severity": "Mild to moderate, usually 3–6/10; the patient often stops what they are doing rather than calling it severe pain", "timing": "Comes on during exertion or emotional stress and eases within a few minutes of rest; reproducible with the same level of activity", "aggravating": ["Walking fast or uphill", "Climbing stairs", "Carrying groceries", "Cold weather", "A heavy meal", "Emotional upset", "Sexual activity"], "relieving": ["Resting or sitting down", "Stopping the activity", "Nitroglycerin under the tongue within 1–5 minutes", "Calming down"], "associated_symptoms": [{"text": "Shortness of breath with the chest discomfort", "frequency": "common"}, {"text": "Feeling of doom or anxiety during the episode", "frequency": "sometimes"}, {"text": "Sweating", "frequency": "sometimes"}, {"text": "Lightheadedness", "frequency": "sometimes"}, {"text": "Nausea or a queasy stomach", "frequency": "sometimes"}, {"text": "Palpitations", "frequency": "sometimes"}, {"text": "Fatigue with activity that used to be easy", "frequency": "common"}], "pertinent_negatives": ["Pain that is sharp and worse with a deep breath or lying flat", "Pain reproduced by pressing on the chest wall", "Pain that lasts only seconds or is constant for hours", "Pain that is burning and worse after meals or when lying down", "Fever", "Coughing up blood", "Recent long car or plane trip with one-sided leg swelling", "Sudden tearing pain that moves from the chest to the back", "Pain that comes only with eating or is relieved by antacids"]}, "ros": [{"system": "constitutional", "positives": [{"text": "Feeling tired more easily", "frequency": "sometimes"}], "negatives": ["Fever", "Chills", "Unintentional weight loss", "Night sweats"]}, {"system": "cardiovascular", "positives": [{"text": "Chest pressure with exertion", "frequency": "almost_always"}, {"text": "Palpitations during episodes", "frequency": "sometimes"}, {"text": "Swelling in the ankles", "frequency": "rare"}], "negatives": ["Chest pain at rest lasting more than 20 minutes", "Pain that wakes them from sleep", "Fainting", "Leg swelling that is new"], "argues_against": ["Constant pain lasting hours", "Pain at rest that is not relieved by nitroglycerin"]}, {"system": "respiratory", "positives": [{"text": "Short of breath when the chest discomfort comes on", "frequency": "common"}], "negatives": ["Coughing up blood", "Pleuritic pain worse with deep breath", "Wheezing", "Recent immobilization with leg swelling"], "argues_against": ["Sudden sharp pain with breathlessness", "Pain worse when lying flat"]}, {"system": "gastrointestinal", "positives": [{"text": "Mild nausea during episodes", "frequency": "sometimes"}, {"text": "Belching that the patient blames on heartburn", "frequency": "sometimes"}], "negatives": ["Vomiting", "Difficulty swallowing", "Pain that is clearly worse after meals or when lying down", "Black or bloody stools"], "argues_against": ["Burning pain relieved by antacids", "Regurgitation of food"]}, {"system": "musculoskeletal", "positives": [], "negatives": ["Pain reproduced by pressing on the chest wall", "Pain worse with twisting or reaching", "Recent chest injury"], "argues_against": ["Chest wall tenderness", "Pain only with certain arm movements"]}, {"system": "neurologic", "positives": [{"text": "Lightheadedness during episodes", "frequency": "sometimes"}], "negatives": ["Fainting", "Sudden weakness on one side", "Slurred speech", "Vision loss"], "argues_against": ["Focal neurologic symptoms"]}, {"system": "psychiatric", "positives": [{"text": "Worry that something is wrong with the heart", "frequency": "common"}, {"text": "Feeling anxious during episodes", "frequency": "sometimes"}], "negatives": ["Panic attacks that come at rest without exertion", "Symptoms that only occur during stressful situations with no exertional trigger"], "argues_against": ["Chest pain only during panic attacks"]}], "atypical": [{"population": "older_adults", "how_it_differs": "May present with shortness of breath, weakness, or confusion rather than chest pain; episodes can be triggered by minimal activity.", "missing_classic_features": ["Chest pain", "Clear exertional pattern"]}, {"population": "diabetes", "how_it_differs": "Neuropathy from long-standing diabetes can blunt the pain, so they report breathlessness, fatigue, or indigestion instead of classic chest pressure.", "missing_classic_features": ["Chest pressure", "Radiating arm pain"]}, {"population": "pregnancy", "how_it_differs": "Chest discomfort is more often attributed to reflux or the increased workload of pregnancy; true angina is uncommon but can occur with pre-existing coronary disease or coronary spasm.", "missing_classic_features": ["Predictable exertional pattern"]}, {"population": "obesity", "how_it_differs": "Symptoms come on with much lighter activity, and shortness of breath may dominate over chest pressure.", "missing_classic_features": ["Chest pain as the main complaint"]}]}, "exam": {"general": {"mild": "Comfortable, no distress at rest; normal appearance", "moderate": "Mild anxiety or discomfort during episodes, otherwise comfortable at rest", "severe": "Diaphoretic, anxious, appears uncomfortable even at rest", "critical": "Ill-appearing, pale, diaphoretic, distressed, may be hypotensive or in pulmonary edema"}, "findings": [{"id": "chest-wall-tenderness", "region": "musculoskeletal", "maneuver": "Palpate the chest wall and reproduce symptoms by pressing on the sternum and ribs", "finding": "No chest wall tenderness", "frequency": "almost_always", "significance": "neutral", "importance": "important"}, {"id": "cardiac-auscultation", "region": "cardiac", "maneuver": "Auscultate the heart at the apex, base, and Erb's point", "finding": "Normal S1 and S2 without murmurs, rubs, or gallops", "frequency": "common", "significance": "neutral", "importance": "important"}, {"id": "s3-gallop", "region": "cardiac", "maneuver": "Auscultate at the apex with the bell", "finding": "S3 gallop suggesting left ventricular dysfunction or volume overload", "frequency": "rare", "min_severity": "severe", "significance": "supports", "importance": "important"}, {"id": "s4-gallop", "region": "cardiac", "maneuver": "Auscultate at the apex with the bell", "finding": "S4 gallop suggesting reduced left ventricular compliance", "frequency": "sometimes", "min_severity": "moderate", "significance": "supports", "importance": "important"}, {"id": "carotid-bruits", "region": "neck", "maneuver": "Auscultate the carotid arteries", "finding": "Carotid bruits suggesting concomitant atherosclerotic disease", "frequency": "sometimes", "significance": "supports", "importance": "important"}, {"id": "jugular-venous-distention", "region": "neck", "maneuver": "Inspect the jugular venous pulse at 45 degrees", "finding": "Elevated jugular venous pressure suggesting heart failure or right heart strain", "frequency": "rare", "min_severity": "severe", "significance": "supports", "importance": "important"}, {"id": "lung-crackles", "region": "lung", "maneuver": "Auscultate the lung fields", "finding": "Bibasilar crackles suggesting pulmonary congestion", "frequency": "rare", "min_severity": "severe", "significance": "supports", "importance": "important"}, {"id": "peripheral-edema", "region": "extremities", "maneuver": "Press the dorsum of each foot and the lower legs", "finding": "Pitting edema suggesting right heart failure", "frequency": "rare", "min_severity": "severe", "significance": "supports", "importance": "important"}, {"id": "peripheral-pulses", "region": "extremities", "maneuver": "Palpate the radial, dorsalis pedis, and posterior tibial pulses", "finding": "Diminished or absent peripheral pulses suggesting diffuse atherosclerosis", "frequency": "sometimes", "significance": "supports", "importance": "important"}, {"id": "xanthomas", "region": "skin", "maneuver": "Inspect the eyelids, tendons, and skin for lipid deposits", "finding": "Xanthelasma or tendon xanthomas suggesting familial hypercholesterolemia", "frequency": "rare", "significance": "supports", "importance": "optional"}, {"id": "tendon-xanthomas", "region": "musculoskeletal", "maneuver": "Palpate the Achilles tendons and extensor tendons of the hands", "finding": "Tendon xanthomas suggesting familial hypercholesterolemia", "frequency": "rare", "significance": "supports", "importance": "optional"}, {"id": "arcus-senilis", "region": "heent", "maneuver": "Inspect the cornea for a gray-white ring at the limbus", "finding": "Arcus senilis suggesting hyperlipidemia", "frequency": "sometimes", "significance": "supports", "importance": "optional"}]}, "vitals": {"hr": {"mild": {"min": 60, "max": 100}, "moderate": {"min": 70, "max": 110}, "severe": {"min": 90, "max": 130}, "critical": {"min": 100, "max": 150}}, "rr": {"mild": {"min": 12, "max": 20}, "moderate": {"min": 14, "max": 22}, "severe": {"min": 18, "max": 28}, "critical": {"min": 22, "max": 32}}, "sbp": {"mild": {"min": 100, "max": 140}, "moderate": {"min": 100, "max": 160}, "severe": {"min": 90, "max": 180}, "critical": {"min": 70, "max": 200}}, "dbp": {"mild": {"min": 60, "max": 90}, "moderate": {"min": 60, "max": 100}, "severe": {"min": 50, "max": 110}, "critical": {"min": 40, "max": 120}}, "spo2": {"mild": {"min": 95, "max": 100}, "moderate": {"min": 92, "max": 98}, "severe": {"min": 88, "max": 95}, "critical": {"min": 80, "max": 92}}}, "labs": [{"test_id": "hs_tnt", "ranges": {"mild": {"min": 0, "max": 14}, "moderate": {"min": 0, "max": 22}}, "frequency": "almost_always", "importance": "essential", "caveat": "Normal or essentially unchanged serial troponins separate stable angina from unstable angina and myocardial infarction; a rise or fall indicates acute