, "caveat": "Identifies undiagnosed diabetes or poor control, both of which worsen prognosis."}, {"test_id": "bnp", "ranges": {"moderate": {"min": 100, "max": 300}, "severe": {"min": 300, "max": 900}}, "frequency": "sometimes", "importance": "optional", "caveat": "Elevated BNP suggests heart failure as an alternative or contributing cause of dyspnea and chest discomfort."}, {"test_id": "tsh", "ranges": {"mild": {"min": 4.0, "max": 6.0}, "moderate": {"min": 6.0, "max": 10.0}, "severe": {"min": 10.0, "max": 20.0}}, "frequency": "sometimes", "importance": "optional", "caveat": "Thyroid disease can precipitate or mimic angina; consider when symptoms are atypical or there are thyroid features."}], "ecg": {"findings": [{"feature": "rhythm", "finding": "Sinus rhythm", "frequency": "almost_always"}, {"feature": "st", "finding": "Horizontal or downsloping ST depression during pain or with exercise", "leads": ["V4", "V5", "V6", "I", "II"], "frequency": "common", "min_severity": "moderate"}, {"feature": "t_wave", "finding": "T wave inversion in the ischemic territory", "leads": ["V4", "V5", "V6", "I", "II"], "frequency": "sometimes", "min_severity": "moderate"}, {"feature": "st", "finding": "Transient ST elevation during spontaneous rest pain (coronary vasospasm)", "leads": ["II", "III", "aVF", "V1", "V2", "V3", "V4", "V5", "V6"], "frequency": "rare", "min_severity": "severe"}, {"feature": "qrs", "finding": "Pathologic Q waves from prior myocardial infarction", "frequency": "sometimes"}, {"feature": "conduction", "finding": "Left bundle branch block or other intraventricular conduction delay", "frequency": "sometimes"}, {"feature": "other", "finding": "Left ventricular hypertrophy from long-standing hypertension", "frequency": "common"}, {"feature": "qt", "finding": "Prolonged QT interval", "frequency": "rare", "min_severity": "severe"}]}, "imaging": [{"study": "Transthoracic echocardiogram", "modality": "echo", "findings": [{"text": "Normal left ventricular systolic function", "frequency": "common"}, {"text": "Regional wall motion abnormality in a coronary distribution", "frequency": "sometimes"}, {"text": "Left ventricular hypertrophy", "frequency": "common"}, {"text": "Diastolic dysfunction", "frequency": "sometimes"}, {"text": "Valvular disease such as aortic stenosis or mitral regurgitation", "frequency": "sometimes"}]}, {"study": "Exercise or pharmacologic stress test with imaging (nuclear perfusion or echocardiography)", "modality": "nuclear", "preferred_when": "Patients who can exercise and have interpretable ECG; pharmacologic stress if unable to exercise", "findings": [{"text": "Reversible perfusion defect in a coronary territory during stress", "frequency": "common"}, {"text": "Fixed perfusion defect suggesting prior infarction", "frequency": "sometimes"}, {"text": "New or worsening regional wall motion abnormality with stress", "frequency": "sometimes"}, {"text": "Normal perfusion and function (negative study)", "frequency": "sometimes"}]}, {"study": "Coronary CT angiography", "modality": "ct", "preferred_when": "Lower-risk patients with atypical symptoms and no known coronary disease", "findings": [{"text": "Coronary artery calcification and atherosclerotic plaque", "frequency": "common"}, {"text": "Stenosis of one or more coronary arteries", "frequency": "common"}, {"text": "No significant coronary stenosis (negative study)", "frequency": "sometimes"}]}, {"study": "Invasive coronary angiography", "modality": "other", "preferred_when": "High-risk features, refractory symptoms, or when revascularization is being considered", "findings": [{"text": "Significant stenosis in one or more epicardial coronary arteries", "frequency": "common"}, {"text": "Multivessel coronary artery disease", "frequency": "sometimes"}, {"text": "Left main or proximal left anterior descending stenosis", "frequency": "sometimes"}, {"text": "No obstructive disease (possible vasospastic or microvascular angina)", "frequency": "sometimes"}]}, {"study": "Chest x-ray", "modality": "xray", "findings": [{"text": "Normal heart size and clear lungs", "frequency": "common"}, {"text": "Cardiomegaly suggesting heart failure", "frequency": "sometimes"}, {"text": "Pulmonary venous congestion or edema", "frequency": "rare"}, {"text": "Widened mediastinum suggesting aortic dissection", "frequency": "rare"}]}], "workup": {"initial": [{"test": "ECG", "why": "First test in any chest pain; identifies ischemia, infarction, or arrhythmia"}, {"test": "hs_tnt", "why": "Distinguishes stable angina from unstable angina or myocardial infarction; serial measurements if initially normal"}, {"test": "cbc", "why": "Detects anemia that can worsen ischemia"}, {"test": "bmp", "why": "Baseline kidney function, electrolytes, and glucose before therapy"}, {"test": "lipids", "why": "Assesses atherosclerotic risk and guides lipid-lowering therapy"}, {"test": "a1c", "why": "Screens for diabetes, a major modifiable risk factor"}, {"test": "Chest x-ray", "why": "Evaluates alternative causes of chest pain and heart size", "only_if": "another cause of chest pain is suspected or the presentation is atypical"}, {"test": "Transthoracic echocardiogram", "why": "Assesses ventricular function and valvular disease", "only_if": "heart failure, murmur, or prior infarction is suspected"}], "confirmatory": [{"test": "Exercise or pharmacologic stress test with imaging (nuclear perfusion or echocardiography)", "why": "Confirms inducible ischemia and risk-stratifies when the diagnosis is uncertain and the patient is stable"}, {"test": "Coronary CT angiography", "why": "Noninvasive anatomic confirmation in lower-risk patients with atypical symptoms"}, {"test": "Invasive coronary angiography", "why": "Definitive anatomic diagnosis and allows revascularization when high-risk features or refractory symptoms are present"}], "supporting": [{"test": "tsh", "why": "Thyroid disease can precipitate or mimic angina", "only_if": "atypical features or suspected thyroid disorder"}, {"test": "bnp", "why": "Helps identify heart failure as an alternative or contributing cause", "only_if": "dyspnea predominates or heart failure is suspected"}, {"test": "d_dimer", "why": "Rules out pulmonary embolism when the presentation is atypical", "only_if": "pulmonary embolism is suspected"}], "not_indicated": [{"test": "d_dimer", "why": "Not routine in typical exertional angina; only if pulmonary embolism is suspected"}, {"test": "lipase", "why": "No role unless the pain is epigastric and pancreatitis is suspected"}, {"test": "ua", "why": "Not helpful in typical angina"}, {"test": "Chest x-ray", "why": "Not routine in classic stable angina with a clear alternate diagnosis"}], "decision_points": ["Obtain an ECG within 10 minutes of presentation and compare with prior tracings", "Serial troponins are required to exclude acute coronary syndrome before labeling symptoms as stable angina", "Do not order a stress test during active or unstable symptoms; risk-stratify and consider early invasive evaluation instead", "Pregnancy test before stress testing or CT angiography in anyone who could be pregnant"], "criteria": [{"name": "Typical (classic) angina", "summary": "Chest discomfort that is substernal, provoked by exertion or emotional stress, and relieved by rest or nitroglycerin within minutes.", "items": ["Substernal chest discomfort of characteristic quality and duration", "Provoked by exertion or emotional stress", "Relieved by rest or nitroglycerin"]}, {"name": "Atypical angina", "summary": "Chest discomfort meeting two of the three typical features.", "items": ["Meets two of: substernal discomfort, provoked by exertion, relieved by rest or nitroglycerin"]}, {"name": "Noncardiac chest pain", "summary": "Chest discomfort meeting one or none of the typical features.", "items": ["Meets one or none of: substernal discomfort, provoked by exertion, relieved by rest or nitroglycerin"]}], "scores": ["grace", "timi_ua_nstemi", "duke_treadmill", "ascvd_risk"]}, "differential": [{"name": "Acute coronary syndrome (unstable angina or myocardial infarction)", "slug": "acute-coronary-syndrome", "why_considered": "Same underlying coronary disease; the key question is whether symptoms are stable or represent an acute plaque event", "must_not_miss": true, "trigger": "Pain at rest, new-onset severe pain, or a change in a previously stable pattern", "discriminators": {"history": ["Symptoms at rest or with minimal activity", "Crescendo pattern over hours to days", "Pain lasting more than 20 minutes", "Not relieved by rest or nitroglycerin"], "exam": ["Diaphoresis, pallor, distress", "New S3 or pulmonary crackles", "Hypotension or tachycardia"], "labs": ["Rising or falling high-sensitivity troponin", "Elevated BNP if heart failure develops"], "imaging": ["New regional wall motion abnormality on echocardiography", "ST depression or elevation on ECG"]}}, {"name": "Aortic dissection", "slug": "aortic-dissection", "why_considered": "Severe chest pain that can radiate to the back and mimic cardiac ischemia", "must_not_miss": true, "trigger": "Sudden severe tearing pain, pulse or blood pressure asymmetry, or a widened mediastinum", "discriminators": {"history": ["Abrupt onset, maximal at the start", "Tearing or ripping quality", "Migrating from chest to back or abdomen", "Marfan syndrome or known aortic aneurysm"], "exam": ["Blood pressure difference between arms", "Pulse deficit", "New aortic regurgitation murmur", "Focal neurologic deficit"], "labs": ["No single lab excludes it; troponin may be normal or mildly elevated"], "imaging": ["Widened mediastinum on chest x-ray", "Intimal flap on CT angiography or transesophageal echocardiography"]}}, {"name": "Pulmonary embolism", "slug": "pulmonary-embolism", "why_considered": "Chest discomfort with shortness of breath and tachycardia", "must_not_miss": true, "trigger": "Pleuritic pain, sudden dyspnea, or hypoxia with a clear chest", "discriminators": {"history": ["Sudden onset of dyspnea", "Recent surgery, immobilization, or long travel", "Prior venous thromboembolism", "Hemoptysis"], "exam": ["Tachycardia out of proportion to findings", "Unilateral leg swelling or calf tenderness", "Clear lungs on auscultation"], "labs": ["Elevated D-dimer", "Hypoxemia with respiratory alkalosis"], "imaging": ["Filling defect on CT pulmonary angiography", "Right heart strain on echocardiography"]}}, {"name": "Gastroesophageal reflux disease", "slug": "gastroesophageal-reflux-disease", "why_considered": "Burning chest discomfort that patients describe as indigestion", "must_not_miss": false, "discriminators": {"history": ["Burning quality, worse after meals or when lying flat", "Relieved by antacids", "No exertional trigger", "Water brash or regurgitation"], "exam": ["Epigastric tenderness", "No cardiac findings"], "labs": ["Typically normal cardiac markers"], "imaging": ["Normal stress testing if performed"]}}, {"name": "Costochondritis", "slug": "costochondritis", "why_considered": "Chest wall pain that can be mistaken for cardiac pain", "must_not_miss": false, "discriminators": {"history": ["Sharp, localized pain", "Worse with deep breath, coughing, or twisting", "No exertional pattern"], "exam": ["Reproducible tenderness at the costochondral junctions", "Pain reproduced by palpation"], "labs": ["Normal troponin and ECG"], "imaging": ["No specific findings"]}}, {"name": "Anxiety or panic attack", "slug": "panic-attack", "why_considered": "Chest tightness with palpitations, sweating, and a sense of doom", "must_not_miss": false, "discriminators": {"history": ["Occurs at rest or during stress without exertion", "Associated with hyperventilation, paresthesias, or fear of dying", "Episodes may last longer than typical angina"], "exam": ["Normal cardiac and pulmonary exam", "Signs of hyperventilation"], "labs": ["Normal troponin and ECG"], "imaging": ["Normal stress testing if performed"]}}, {"name": "Aortic stenosis", "slug": "aortic-stenosis", "why_considered": "Exertional chest pain, dyspnea, and syncope from outflow obstruction", "must_not_miss": false, "discriminators": {"history": ["Exertional syncope or near-syncope", "Dyspnea on exertion", "Symptoms may progress rapidly"], "exam": ["Harsh crescendo-decrescendo systolic murmur radiating to the carotids", "Diminished S2", "Pulsus parvus et tardus"], "labs": ["Elevated BNP if heart failure develops"], "imaging": ["Calcified, restricted aortic valve with elevated gradient on echocardiography"]}}], "course": {"severity": {"mild": "Stable angina with symptoms only at high levels of exertion; normal vitals and exam; normal troponin and ECG", "moderate": "Stable angina with symptoms at moderate activity; may have risk factors and ECG changes such as LVH or prior Q waves; troponin normal", "severe": "Unstable pattern or symptoms at rest; ECG may show ST depression or T wave inversion; troponin may be normal or slightly elevated; hemodynamics stable", "critical": "Ongoing ischemic pain with hemodynamic instability, pulmonary edema, or malignant arrhythmia; troponin rising; requires immediate reperfusion"}, "red_flags": [{"finding": "Pain at rest or lasting more than 20 minutes", "meaning": "Unstable angina or myocardial infarction until proven otherwise"}, {"finding": "New ST depression or elevation on ECG", "meaning": "Acute ischemia; needs urgent risk stratification and possible reperfusion"}, {"finding": "Rising or falling troponin", "meaning": "Myocardial injury or infarction"}, {"finding": "Hypotension, tachycardia, or new pulmonary crackles", "meaning": "Cardiogenic shock or acute heart failure from severe ischemia"}, {"finding": "Syncope with exertional chest pain", "meaning": "Severe outflow obstruction or arrhythmia; evaluate urgently"}], "complications": [{"name": "Myocardial infarction", "timing": "any", "seriousness": "life_threatening", "frequency": "sometimes", "clues": ["Prolonged rest pain", "Rising troponin", "New ST changes"]}, {"name": "Heart failure", "timing": "late", "seriousness": "serious", "frequency": "sometimes", "clues": ["Progressive dyspnea", "Crackles", "Elevated BNP"]}, {"name": "Arrhythmia (ventricular tachycardia or fibrillation)", "timing": "any", "seriousness": "life_threatening", "frequency": "rare", "clues": ["Palpitations", "Syncope", "Wide-complex tachycardia on monitor"]}, {"name": "Sudden cardiac death", "timing": "any", "seriousness": "life_threatening", "frequency": "rare", "clues": ["Collapse", "Absent pulses", "Ventricular arrhythmia"]}], "special_populations": [{"population": "older_adults", "differences": "May present with dyspnea, weakness, or confusion rather than chest pain; symptoms can be triggered by minimal activity."}, {"population": "diabetes", "differences": "Neuropathy can blunt pain, so they report breathlessness, fatigue, or indigestion instead of classic chest pressure."}, {"population": "pregnancy", "differences": "Chest discomfort is more often attributed to reflux or the increased workload of pregnancy; true angina is uncommon but can occur with pre-existing coronary disease or coronary spasm."}, {"population": "obesity", "differences": "Symptoms come on with much lighter activity, and shortness of breath may dominate over chest pressure."}]}, "teaching": {"key_questions": [{"question": "What does the discomfort feel like?", "category": "hpi", "importance": "essential", "looking_for": "Pressure, squeezing, tightness, or heaviness rather than sharp or stabbing"}, {"question": "Where do you feel it, and does it spread anywhere?", "category": "hpi", "importance": "essential", "looking_for": "Mid-chest or substernal, radiating to the left shoulder, inner left arm, neck, jaw, or back"}, {"question": "What brings it on?", "category": "hpi", "importance": "essential", "looking_for": "Exertion or emotional stress; reproducible at the same level of activity"}, {"question": "What makes it go away, and how quickly?", "category": "hpi", "importance": "essential", "looking_for": "Resolves within minutes of rest or with nitroglycerin under the tongue"}, {"question": "How long does each episode last?", "category": "hpi", "importance": "essential", "looking_for": "About 2 to 10 minutes; longer than 20 minutes suggests acute coronary syndrome"}, {"question": "Has the pattern changed recently — is it coming on with less activity, or at rest?", "category": "red_flag", "importance": "essential", "looking_for": "A crescendo pattern or rest pain means unstable angina until proven otherwise"}, {"question": "Do you get short of breath, sweat, feel nauseated, or lightheaded with the episodes?", "category": "associated", "importance": "important", "looking_for": "Associated dyspnea, diaphoresis, nausea, or lightheadedness supporting myocardial ischemia"}, {"question": "Does the pain change with a deep breath, coughing, or pressing on your chest?", "category": "associated", "importance": "important", "looking_for": "Absent; present suggests a musculoskeletal or pleural cause"}, {"question": "Does it burn after meals or when you lie down, and do antacids help?", "category": "associated", "importance": "important", "looking_for": "Absent; present suggests gastroesophageal reflux"}, {"question": "Have you ever had a heart attack, stent, or bypass?", "category": "pmh", "importance": "essential", "looking_for": "Known coronary artery disease raises the likelihood of angina"}, {"question": "Do you have high blood pressure, diabetes, or high cholesterol?", "category": "pmh", "importance": "essential", "looking_for": "Major modifiable atherosclerotic risk factors"}, {"question": "Do you smoke, or have you smoked?", "category": "social", "importance": "essential", "looking_for": "Current or former smoking, a strong risk factor"}, {"question": "Has anyone in your family had a heart attack or bypass at a young age?", "category": "family", "importance": "important", "looking_for": "Early coronary disease in a first-degree relative"}, {"question": "Do you use cocaine, amphetamines, or any stimulants?", "category": "social", "importance": "important", "looking_for": "Stimulant use that can provoke coronary spasm or ischemia"}, {"question": "What medications do you take, including anything for chest pain?", "category": "medications", "importance": "important", "looking_for": "Nitroglycerin use and response, plus drugs that can trigger spasm such as triptans or ergots"}, {"question": "Any fever, coughing up blood, or recent long travel with leg swelling?", "category": "ros", "importance": "important", "looking_for": "Absent; present points toward infection, pulmonary embolism, or another cause"}, {"question": "Any sudden tearing pain that moved from your chest to your back?", "category": "red_flag", "importance": "essential", "looking_for": "Absent; present raises concern for aortic dissection"}], "accepted_names": ["Angina", "Angina pectoris", "Stable angina", "Stable angina pectoris", "Chronic stable angina", "Exertional angina"], "reasoning_points": ["Substernal chest pressure provoked by exertion or emotional stress and relieved by rest or nitroglycerin within minutes", "Episodes last about 2 to 10 minutes and are reproducible at a similar level of activity", "Radiation to the left shoulder, inner left arm, neck, or jaw", "Associated dyspnea, diaphoresis, or nausea during episodes", "Coronary risk factors such as hypertension, diabetes, hyperlipidemia, and smoking", "ECG without acute ST elevation and serial high-sensitivity troponins that are normal or unchanged, excluding acute coronary syndrome", "Alternative causes of chest pain such as aortic dissection, pulmonary embolism, reflux, and chest wall pain considered and excluded", "A change in pattern or rest pain would reclassify the presentation as unstable angina"], "difficulty": {"easy": ["Middle-aged or older adult with classic exertional chest pressure relieved by rest", "Clear coronary risk factors such as smoking, hypertension, and diabetes", "Normal troponin and no acute ECG changes", "Symptoms reproducible with the same level of activity"], "medium": ["Older adult or patient with diabetes presenting with exertional dyspnea or fatigue instead of chest pain", "Atypical features such as jaw, back, or epigastric discomfort", "ECG showing LVH or prior Q waves that complicate interpretation", "Symptoms that overlap with reflux or musculoskeletal pain"], "hard": ["Younger patient with few traditional risk factors and atypical symptoms", "Rest or nocturnal pain suggesting vasospastic angina", "Chest pain in pregnancy attributed to reflux or increased cardiac workload", "Presentation with nonspecific symptoms and a nondiagnostic ECG requiring stress testing or coronary imaging to confirm"]}}}$rounds_kb$::jsonb)
