": "common"}, {"text": "Vomiting that started after the pain", "frequency": "common"}, {"text": "Feeling warm or having chills", "frequency": "sometimes"}, {"text": "Constipation", "frequency": "sometimes"}, {"text": "Not able to pass gas", "frequency": "sometimes"}, {"text": "Diarrhea", "frequency": "rare"}], "pertinent_negatives": ["Vomiting before the pain began", "Profuse watery diarrhea", "Burning or pain with urination", "Flank pain that comes in waves", "Vaginal bleeding or a missed period", "Prior appendectomy", "Sick contacts with the same illness"]}, "ros": [{"system": "constitutional", "positives": [{"text": "Feeling warm", "frequency": "sometimes"}, {"text": "Low energy", "frequency": "sometimes"}], "negatives": ["Weight loss", "Night sweats"]}, {"system": "gastrointestinal", "positives": [{"text": "Nausea", "frequency": "common"}, {"text": "Vomiting", "frequency": "common"}, {"text": "Poor appetite", "frequency": "common"}], "negatives": ["Blood in the stool", "Black stools", "Yellowing of the eyes or skin"], "argues_against": ["Vomiting that came before the pain", "Profuse diarrhea"]}, {"system": "genitourinary", "positives": [], "negatives": ["Pain or burning with urination", "Blood in the urine", "Flank pain"], "argues_against": ["Colicky flank pain radiating to the groin"]}, {"system": "reproductive", "positives": [], "negatives": ["Vaginal discharge", "Vaginal bleeding", "Missed period"], "argues_against": ["Sudden one-sided pelvic pain with vomiting", "Missed period"]}], "atypical": [{"population": "children", "how_it_differs": "Young children cannot describe the pain moving; they show up irritable, vomiting, and refusing to walk or be touched.", "missing_classic_features": ["Clear story of pain migration", "Localized right lower quadrant pain"]}, {"population": "older_adults", "how_it_differs": "Pain is milder, fever may be low or absent, and the white count can be near normal even when the appendix is already perforated.", "missing_classic_features": ["Fever", "Marked leukocytosis", "Severe pain"]}, {"population": "pregnancy", "how_it_differs": "As the uterus grows the appendix is pushed upward, so pain may be in the right flank or upper right abdomen and nausea and vomiting are blamed on pregnancy.", "missing_classic_features": ["Right lower quadrant location", "Clear distinction from pregnancy symptoms"]}, {"population": "obesity", "how_it_differs": "Thicker abdominal wall makes the exam less reliable and imaging harder to interpret, so pain may feel less localized and the exam less impressive than the disease.", "missing_classic_features": ["Sharp localized tenderness"]}]}, "exam": {"general": {"mild": "Uncomfortable but not ill-appearing; lies still and prefers not to move", "moderate": "Lies still with knees drawn up, winces when the stretcher is bumped or with coughing", "severe": "Ill-appearing and flushed, reluctant to move, guarded when approached", "critical": "Toxic-appearing, pale and diaphoretic, quiet or lethargic, peritonitic"}, "findings": [{"id": "rlq-tenderness", "region": "abdomen", "maneuver": "Palpate all four quadrants, starting in the quadrant farthest from the pain and saving the right lower quadrant for last", "finding": "Tenderness localized to the right lower quadrant", "frequency": "almost_always", "significance": "strongly_supports", "importance": "essential"}, {"id": "mcburney-point-tenderness", "region": "abdomen", "maneuver": "Press at McBurney point, about one-third of the way from the right anterior superior iliac spine to the umbilicus", "finding": "Focal point tenderness at McBurney point", "frequency": "common", "significance": "strongly_supports", "importance": "important"}, {"id": "voluntary-guarding", "region": "abdomen", "maneuver": "Palpate the right lower quadrant gently", "finding": "Voluntary guarding of the abdominal wall muscles", "frequency": "common", "min_severity": "moderate", "significance": "supports", "importance": "important"}, {"id": "cough-tenderness", "region": "abdomen", "maneuver": "Ask the patient to cough, or gently tap the heel or bump the stretcher", "finding": "Sharp pain in the right lower quadrant with jarring, suggesting peritoneal irritation", "frequency": "sometimes", "min_severity": "moderate", "significance": "supports", "importance": "important"}, {"id": "rebound-tenderness", "region": "abdomen", "maneuver": "Press slowly and deeply in the right lower quadrant, then release quickly", "finding": "Pain worse on release than on pressing", "frequency": "sometimes", "min_severity": "moderate", "significance": "supports", "importance": "important"}, {"id": "rovsing-sign", "region": "abdomen", "maneuver": "Press in the left lower quadrant", "finding": "Pain referred to the right lower quadrant", "frequency": "sometimes", "significance": "supports", "importance": "optional"}, {"id": "psoas-sign", "region": "abdomen", "maneuver": "With the patient on the left side, extend the right hip", "finding": "Right lower quadrant pain, suggesting a retrocecal appendix", "frequency": "sometimes", "significance": "supports", "importance": "optional"}, {"id": "obturator-sign", "region": "abdomen", "maneuver": "Flex the right hip and knee and internally rotate the hip", "finding": "Hypogastric or pelvic pain, suggesting a pelvic appendix", "frequency": "rare", "significance": "supports", "importance": "optional"}, {"id": "rigid-abdomen", "region": "abdomen", "maneuver": "Palpate the whole abdomen lightly", "finding": "Diffuse rigidity with involuntary guarding, suggesting generalized peritonitis", "frequency": "rare", "min_severity": "critical", "significance": "strongly_supports", "importance": "essential"}, {"id": "hypoactive-bowel-sounds", "region": "abdomen", "maneuver": "Auscultate the abdomen in all four quadrants", "finding": "Hypoactive bowel sounds", "frequency": "sometimes", "min_severity": "moderate", "significance": "supports", "importance": "optional"}, {"id": "no-organomegaly-or-mass", "region": "abdomen