p", "why": "Adds to the white count in scoring and suggests perforation when high"}, {"test": "MRI abdomen and pelvis without contrast", "why": "Avoids radiation", "only_if": "pregnant and ultrasound nondiagnostic"}], "not_indicated": [{"test": "Abdominal x-ray", "why": "Rarely changes management"}, {"test": "d_dimer", "why": "No role in right lower quadrant pain"}, {"test": "lipase", "why": "Not needed unless the pain is epigastric"}], "decision_points": ["Pregnancy test before CT in anyone who could be pregnant", "Ultrasound first in children and pregnancy; CT if nondiagnostic in nonpregnant patients", "Peritonitis or instability goes to surgery without waiting for imaging"], "criteria": [], "scores": ["alvarado", "pediatric_appendicitis_score"]}, "differential": [{"name": "Ectopic pregnancy", "slug": "ectopic-pregnancy", "why_considered": "Lower abdominal pain in a patient who could be pregnant; can mimic appendicitis closely and is life-threatening.", "must_not_miss": true, "trigger": "Any patient of childbearing potential with abdominal pain, especially with a missed period or vaginal bleeding.", "discriminators": {"history": ["Missed period", "Vaginal bleeding or spotting", "Pain may be sudden and severe", "Prior ectopic pregnancy or tubal surgery"], "exam": ["Adnexal tenderness or mass", "Peritoneal signs possible", "Cervical motion tenderness"], "labs": ["Positive hCG", "Falling hematocrit if bleeding"], "imaging": ["No intrauterine pregnancy on transvaginal ultrasound", "Free fluid in the pelvis", "Adnexal mass"]}}, {"name": "Ovarian torsion", "slug": "ovarian-torsion", "why_considered": "Sudden one-sided lower abdominal pain with nausea and vomiting, often in a young patient.", "must_not_miss": true, "trigger": "Abrupt onset of severe one-sided pelvic pain with vomiting at the start.", "discriminators": {"history": ["Sudden onset, often while moving or exercising", "Vomiting at or near onset", "Known ovarian cyst"], "exam": ["Adnexal tenderness", "Unilater