max": 95}, "severe": {"min": 88, "max": 92}, "critical": {"min": 80, "max": 88}}}, "labs": [{"test_id": "eos_pct", "ranges": {"mild": {"min": 4, "max": 8}, "moderate": {"min": 5, "max": 10}, "severe": {"min": 6, "max": 12}}, "frequency": "sometimes", "importance": "optional", "caveat": "A modest eosinophilia supports an allergic (atopic) phenotype but is neither sensitive nor specific; a normal value does not argue against asthma."}, {"test_id": "crp", "ranges": {"moderate": {"min": 1.0, "max": 3.0}, "severe": {"min": 2.0, "max": 6.0}}, "frequency": "rare", "importance": "optional", "caveat": "Usually normal in asthma; a marked elevation points toward pneumonia or another infection rather than asthma."}, {"test_id": "wbc", "ranges": {"moderate": {"min": 11.0, "max": 14.0}, "severe": {"min": 12.0, "max": 16.0}}, "frequency": "rare", "importance": "optional", "caveat": "Mild leukocytosis is uncommon in uncomplicated asthma and should prompt consideration of a concurrent infection."}], "ecg": {"findings": [{"feature": "rate", "finding": "Sinus tachycardia", "frequency": "common", "min_severity": "moderate"}, {"feature": "other", "finding": "Right axis deviation or prominent right atrial and right ventricular forces suggesting chronic hypoxemia or pulmonary hypertension", "frequency": "rare", "min_severity": "severe"}]}, "imaging": [{"study": "Chest x-ray, two views", "modality": "xray", "findings": [{"text": "Normal or hyperinflated lungs with flattened diaphragms", "frequency": "common"}, {"text": "Peribronchial cuffing or thickened bronchial walls", "frequency": "sometimes"}, {"text": "Patchy atelectasis, especially of the right middle lobe", "frequency": "sometimes"}, {"text": "Focal consolidation suggesting pneumonia", "frequency": "rare"}, {"text": "Hyperlucent lung field with mediastinal shift suggesting a foreign body or pneumothorax", "frequency": "rare"}]}], "workup": {"initial": [{"test": "Spirometry", "why": "Confirms airflow obstruction and reversibility in children old enough to perform the maneuver (usually age 5 and older)"}, {"test": "Peak flow", "why": "Office or home measurement of peak expiratory flow; useful for monitoring and for older children who can cooperate"}, {"test": "Chest x-ray, two views", "why": "Not routine; helps exclude pneumonia, foreign body, or other structural causes", "only_if": "the presentation is atypical, the first episode is severe, or another diagnosis is suspected"}], "confirmatory": [], "supporting": [{"test": "Allergy skin test", "why": "Identifies allergic triggers and supports an atopic phenotype", "only_if": "there is a history of allergies or the trigger pattern is unclear"}, {"test": "Allergen specific ige", "why": "Alternative to skin testing when skin testing is not feasible", "only_if": "skin testing is unavailable or not tolerated"}, {"test": "Therapeutic trial of inhaled corticosteroid", "why": "A trial of controller therapy with reassessment is often used to support the diagnosis in young children who cannot perform spirometry", "only_if": "the child is too young for reliable lung function testing"}], "not_indicated": [{"test": "cbc", "why": "Not needed for a typical asthma presentation; a normal white count does not change management"}, {"test": "crp", "why": "Not routinely helpful; reserve for concern about bacterial infection"}, {"test": "procalcitonin", "why": "No role in asthma; consider only if bacterial pneumonia is suspected"}, {"test": "Ct chest", "why": "Not indicated for routine asthma evaluation; reserve for suspected structural or interstitial disease"}, {"test": "Chest x-ray, two views", "why": "Not routine for a typical, previously diagnosed asthma exacerbation", "only_if": "the presentation is atypical, the first episode is severe, or another diagnosis is suspected"}], "decision_points": ["Spirometry requires a child old enough to perform forced expiratory maneuvers reliably, usually age 5 or older; younger children are diagnosed clinically and by treatment response", "A chest x-ray is not routine for a typical exacerbation but should be obtained when the presentation is atypical or a complication is suspected", "Consider a trial of controller therapy with reassessment when the diagnosis is uncertain in a young child", "Assess for alternative diagnoses such as foreign body aspiration, bronchiolitis, or structural airway lesions when symptoms are atypical"], "criteria": [{"name": "Clinical diagnosis of asthma in children", "summary": "Diagnosis is based on a history of recurrent episodes of wheezing, cough, chest tightness, or difficulty breathing, often worse at night or with triggers such as exercise, cold air, allergens, or viral infections, together with evidence of variable expiratory airflow limitation. In children old enough for spirometry, airflow obstruction that improves after a bronchodilator supports the diagnosis. In younger children, a documented response to a trial of asthma therapy can support the diagnosis."}], "scores": []}, "differential": [{"name": "Bronchiolitis", "slug": "bronchiolitis", "why_considered": "Wheezing and respiratory distress in a young child, especially during viral season", "must_not_miss": false, "discriminators": {"history": ["Age under 2 years, most often under 12 months", "Symptoms begin with a runny nose and low-grade fever, then cough and wheeze over 1 to 2 days", "First episode, no prior recurrent wheeze", "Sick contacts with colds"], "exam": ["Diffuse fine crackles and wheeze", "Low-grade fever", "No response to bronchodilator"], "labs": ["Viral testing positive for RSV or another respiratory virus"], "imaging": ["Chest x-ray with hyperinflation and perihilar streaking; not routinely needed"]}}, {"name": "Foreign body aspiration", "slug": "foreign-body-aspiration", "why_considered": "Sudden wheezing or coughing in a toddler who was playing with small objects", "must_not_miss": true, "trigger": "Abrupt onset of wheeze or cough while eating or playing with a small object, or a focal unilateral wheeze", "discriminators": {"history": ["Sudden onset during eating, playing, or laughing", "Choking episode witnessed or suspected", "Symptoms may be intermittent and unilateral", "No prior recurrent wheeze"], "exam": ["Focal decreased breath sounds or unilateral wheeze", "Stridor if the object is in the upper airway", "Asymmetric chest expansion"], "imaging": ["Hyperlucent lung field with air trapping and mediastinal shift on expiratory or decubitus views", "Object may be radiolucent and not visible on plain film"]}}, {"name": "Pneumonia", "slug": "community-acquired-pneumonia", "why_considered": "Cough, tachypnea, and respiratory distress in a febrile child", "must_not_miss": false, "discriminators": {"history": ["Fever as a prominent feature", "Productive cough", "Acute onset over 1 to 2 days", "No prior recurrent episodes"], "exam": ["Focal crackles or dullness to percussion", "Fever", "Tachypnea without prominent wheeze"], "labs": ["Leukocytosis with neutrophilia", "Elevated CRP or procalcitonin"], "imaging": ["Focal consolidation on chest x-ray"]}}, {"name": "Cystic fibrosis", "slug": "cystic-fibrosis", "why_considered": "Recurrent wheezing and respiratory symptoms in a young child", "must_not_miss": true, "trigger": "Failure to thrive, chronic productive cough, recurrent sinopulmonary infections, or salty-tasting skin", "discriminators": {"history": ["Poor weight gain or failure to thrive despite adequate intake", "Chronic productive cough", "Recurrent pneumonia or sinusitis", "Greasy, foul-smelling stools", "Family history of cystic fibrosis"], "exam": ["Digital clubbing", "Nasal polyps", "Poor growth", "Salty-tasting skin"], "labs": ["Elevated sweat chloride on sweat testing", "Genetic testing showing CFTR mutations", "Low fecal elastase if pancreatic insufficiency"], "imaging": ["Chest x-ray with bronchiectasis, hyperinflation, or mucus plugging"]}}, {"name": "Gastroesophageal reflux with aspiration", "slug": "gastroesophageal-reflux-disease", "why_considered": "Cough and wheeze in an infant, especially around feeds", "must_not_miss": false, "discriminators": {"history": ["Symptoms worse after feeding or when lying flat", "Frequent spitting up or vomiting", "Choking or gagging with feeds", "Poor weight gain"], "exam": ["Poor weight gain", "Nocturnal cough", "No response to bronchodilator"], "labs": ["Normal eosinophil count", "pH-impedance study showing reflux episodes"], "imaging": ["Upper GI series may show reflux or aspiration"]}}, {"name": "Vocal cord dysfunction", "slug": "vocal-cord-dysfunction", "why_considered": "Episodic breathlessness and noisy breathing in an older child or teen", "must_not_miss": false, "discriminators": {"history": ["Symptoms occur at rest or with stress, not primarily with exercise", "Nocturnal symptoms are uncommon", "Poor response to asthma controller therapy", "Symptoms may be triggered by anxiety or strong emotions"], "exam": ["Inspiratory stridor or hoarseness", "Wheeze loudest over the neck rather than the chest", "Normal oxygen saturation during severe symptoms"], "labs": ["Normal spirometry between episodes", "Flow-volume loop with inspiratory flattening"], "imaging": ["Normal chest x-ray"]}}, {"name": "Allergic rhinitis", "slug": "allergic-rhinitis", "why_considered": "Chronic cough and nasal symptoms in an atopic child", "must_not_miss": false, "discriminators": {"history": ["Prominent sneezing, itchy eyes, and clear nasal discharge", "Symptoms seasonal or with allergen exposure", "Cough is postnasal drip related, not wheeze"], "exam": ["Pale, boggy nasal turbinates", "Allergic shiners and nasal crease", "No wheeze or prolonged expiration"], "labs": ["Positive allergy testing"], "imaging": ["Not needed"]}}, {"name": "Structural airway lesion", "slug": "tracheomalacia", "why_considered": "Persistent noisy breathing or wheeze in an infant without symptom-free periods", "must_not_miss": false, "discriminators": {"history": ["Symptoms present since birth or early infancy", "No clear symptom-free intervals", "Worse with feeding or crying", "May have been intubated or have vascular ring"], "exam": ["Monophonic wheeze or stridor", "Symptoms may change with position"], "imaging": ["Bronchoscopy showing airway compression or malacia", "Chest x-ray or CT showing vascular ring"]}}], "course": {"severity": {"mild": "Symptoms less than twice a week, nighttime symptoms less than twice a month, no limitation of activity, FEV1 at or above 80% predicted, exacerbations brief and rare", "moderate": "Symptoms daily, nighttime symptoms more than once a week, some activity limitation, FEV1 60 to 80% predicted, exacerbations affect activity and sleep", "severe": "Symptoms throughout the day, nighttime symptoms most nights, marked activity limitation, FEV1 below 60% predicted, frequent exacerbations requiring oral corticosteroids", "critical": "Life-threatening exacerbation with exhaustion, minimal air movement, silent chest, cyanosis, altered mental status, or impending respiratory failure requiring intensive care"}, "red_flags": [{"finding": "Silent chest or minimal air movement despite severe distress", "meaning": "Impending respiratory failure; needs immediate escalation"}, {"finding": "Cyanosis of lips, tongue, or nail beds", "meaning": "Severe hypoxemia; give oxygen and prepare for advanced support"}, {"finding": "Exhaustion, confusion, or lethargy", "meaning": "Respiratory fatigue and impending failure"}, {"finding": "Unable to speak in full sentences or feed", "meaning": "Severe exacerbation requiring urgent treatment"}, {"finding": "Oxygen saturation below 90% on room air", "meaning": "Severe hypoxemia; needs continuous monitoring and aggressive therapy"}, {"finding": "Sudden onset of wheeze while eating or playing with a small object", "meaning": "Foreign body aspiration until proven otherwise"}, {"finding": "Poor weight gain, chronic productive cough, or clubbing", "meaning": "Consider cystic fibrosis or another chronic condition"}], "complications": [{"name": "Acute severe exacerbation requiring emergency care or hospitalization", "timing": "any", "seriousness": "serious", "frequency": "common", "clues": ["Increasing rescue inhaler use", "Nighttime awakening", "Tachypnea, retractions, hypoxemia"]}, {"name": "Respiratory failure", "timing": "any", "seriousness": "life_threatening", "frequency": "rare", "clues": ["Silent chest", "Cyanosis", "Exhaustion or altered mental status"]}, {"name": "Atelectasis", "timing": "any", "seriousness": "serious", "frequency": "sometimes", "clues": ["Persistent focal decreased breath sounds", "Patchy opacity on chest x-ray"]}, {"name": "Pneumothorax", "timing": "any", "seriousness": "life_threatening", "frequency": "rare", "clues": ["Sudden pleuritic chest pain", "Unilateral decreased breath sounds", "Tracheal deviation"]}, {"name": "Airway remodeling with persistent airflow limitation", "timing": "late", "seriousness": "serious", "frequency": "sometimes", "clues": ["Long-standing poorly controlled symptoms", "Reduced FEV1 that does not fully reverse"]}, {"name": "Growth impairment and school absenteeism", "timing": "late", "seriousness": "minor", "frequency": "sometimes", "clues": ["Frequent missed school days", "Poor weight gain", "Frequent oral corticosteroid courses"]}], "special_populations": [{"population": "infants", "differences": "Cannot report symptoms; present with feeding difficulty, rapid breathing, and irritability. Wheezing may be the only sign and is hard to distinguish from bronchiolitis. Spirometry is not possible."}, {"population": "children", "differences": "Young children often cannot perform spirometry and may not report chest tightness; diagnosis is clinical and may rely on a trial of controller therapy. Boys are more commonly affected before puberty."}, {"population": "obesity", "differences": "Breathlessness with activity and reduced exercise tolerance are more prominent and may be attributed to weight, delaying diagnosis. Response to controller therapy may be reduced."}, {"population": "pregnancy", "differences": "Adolescent pregnancy may be accompanied by changes in asthma control; some improve and some worsen. Poorly controlled asthma increases risk of preterm birth and low birth weight."}]}, "teaching": {"key_questions": [{"question": "How often do the wheezing or coughing episodes happen, and how long do they last?", "category": "hpi", "importance": "essential", "looking_for": "Recurrent episodes over weeks to months, not a single continuous illness; frequency and duration help grade severity"}, {"question": "Does your child cough or wheeze at night or early in the morning?", "category": "hpi", "importance": "essential", "looking_for": "Nighttime or early morning symptoms, a hallmark of asthma"}, {"question": "What seems to bring it on?", "category": "hpi", "importance": "essential", "looking_for": "Exercise, cold air, dust, pets, pollen, smoke, or colds; a clear trigger pattern supports asthma"}, {"question": "Does the breathing medicine (albuterol) help, and how quickly?", "category": "medications", "importance": "essential", "looking_for": "Rapid relief after a bronchodilator supports reversible airflow obstruction"}, {"question": "How many days of school or play has your child missed?", "category": "social", "importance": "important", "looking_for": "Missed school or limited activity suggests poor control"}, {"question": "Is there any wheezing or noisy breathing between episodes, or does your child feel completely well?", "category": "hpi", "importance": "important", "looking_for": "Symptom-free intervals favor asthma over structural or chronic disease"}, {"question": "Did the wheezing start suddenly while eating or playing with a small object?", "category": "red_flag", "importance": "essential", "looking_for": "Abrupt onset with choking suggests foreign body aspiration, not asthma"}, {"question": "Has your child ever had a cough or wheeze that has never gone away since birth?", "category": "red_flag", "importance": "important", "looking_for": "Continuous symptoms since birth suggest a structural airway lesion or another chronic disease"}, {"question": "Does your child have eczema, hay fever, or food allergies?", "category": "pmh", "importance": "important", "looking_for": "Atopic history supports an allergic asthma phenotype"}, {"question": "Does anyone in the family have asthma, eczema, or hay fever?", "category": "family", "importance": "important", "looking_for": "Family history of atopy, especially maternal asthma"}, {"question": "Does anyone smoke in the home or around your child?", "category": "social", "importance": "essential", "looking_for": "Secondhand smoke exposure, a strong modifiable trigger"}, {"question": "What is the home like - any pets, mold, dampness, cockroaches, or mice?", "category": "social", "importance": "important", "looking_for": "Indoor allergens that can be reduced"}, {"question": "Does your child have trouble feeding or sucking, or is he or she tiring during feeds?", "category": "associated", "importance": "important", "looking_for": "Feeding difficulty in infants suggests significant respiratory distress"}, {"question": "Has your child had any fever, weight loss, night sweats, or poor weight gain?", "category": "ros", "importance": "important", "looking_for": "Absent in typical asthma; present suggests infection, cystic fibrosis, or another diagnosis"}, {"question": "Is your child taking any medicines, including aspirin or ibuprofen?", "category": "medications", "importance": "optional", "looking_for": "Aspirin or NSAID exposure can trigger bronchospasm in some children"}], "accepted_names": ["Asthma", "Childhood asthma", "Pediatric asthma", "Reactive airway disease", "Asthma exacerbation", "Acute asthma exacerbation"], "reasoning_points": ["Recurrent episodes of wheezing, cough, chest tightness, or difficulty breathing separated by symptom-free periods", "Symptoms worse at night or early morning and provoked by typical triggers such as exercise, cold air, allergens, smoke, or viral infections", "Evidence of variable expiratory airflow limitation, such as improvement after a bronchodilator on spirometry or a documented response to a trial of asthma therapy", "Atopic history or family history of asthma and allergy supporting the diagnosis", "Alternative diagnoses considered and excluded, including foreign body aspiration, bronchiolitis, pneumonia, cystic fibrosis, and structural airway lesions", "Severity graded from symptom frequency, nighttime awakenings, activity limitation, and lung function to guide therapy"], "difficulty": {"easy": ["School-age child with recurrent wheezing episodes and clear symptom-free intervals", "Symptoms worse at night and with exercise or cold air", "Personal or family history of eczema, allergic rhinitis, or asthma", "Wheezing that improves with albuterol", "Spirometry showing reversible obstruction"], "medium": ["Preschool child too young for reliable spirometry, diagnosed clinically and by response to a controller trial", "Symptoms only with colds, mistaken for recurrent respiratory infections", "Wheezing with exercise only, without nighttime symptoms", "Coexisting allergic rhinitis or obesity obscuring the picture"], "hard": ["Infant with wheezing and feeding difficulty, hard to distinguish from bronchiolitis", "Toddler with sudden focal wheeze after playing with a small object (foreign body)", "Child with chronic productive cough, poor weight gain, or clubbing suggesting cystic fibrosis", "Teenager with episodic breathlessness and noisy breathing that is actually vocal cord dysfunction", "Severe exacerbation with a quiet chest, cyanosis, or exhaustion"]}}}$rounds_kb$::jsonb)
