chomycosis", "Tinea cruris or tinea corporis"], "family_history": ["Often a household member with the same foot rash or fungal nail infection"], "social_history": ["Athlete or regular gym-goer", "Military service or communal living", "Occupational exposure to wet floors (e.g., pool staff, cleaners)"], "exposures": ["Communal showers or locker room floors", "Swimming pools", "Shared footwear or towels", "Hot, humid weather"], "risk_medications": ["Prednisone", "Tacrolimus", "Cyclosporine", "Methotrexate", "Adalimumab", "Infliximab"]}, "presentation": {"chief_complaints": [{"text": "The skin between my toes is itchy and peeling", "frequency": "almost_always"}, {"text": "My feet itch and burn, especially at night", "frequency": "common"}, {"text": "The skin on my feet is cracked and scaly", "frequency": "common"}, {"text": "My feet smell bad and the skin looks white and soggy", "frequency": "sometimes"}], "hpi": {"onset": "Gradual over days to weeks; often noticed after a gym, pool, or shower exposure", "duration": "Usually present for 1–4 weeks before the patient seeks care; may be recurrent over months or years", "progression": "Starts between the toes, especially the fourth and fifth web space, then spreads to the sole or dorsum; may wax and wane", "location": "Most often the web spaces between the toes, especially between the fourth and fifth toes; can involve the sole, heel, or top of the foot", "radiation": "Not applicable", "quality": "Itchy, burning, peeling, cracked, or macerated skin", "severity": "Mild to moderate; itching can be intense and disrupt sleep", "timing": "Itching is often worse at night or after removing shoes and socks", "aggravating": ["Sweating", "Wearing closed shoes all day", "Warm, humid weather", "Walking barefoot in public showers or locker rooms"], "relieving": ["Keeping feet dry", "Wearing sandals or open shoes", "Over-the-counter antifungal cream", "Cool water soaks"], "associated_symptoms": [{"text": "Peeling or scaling between the toes", "frequency": "almost_always"}, {"text": "Itching", "frequency": "almost_always"}, {"text": "Burning or stinging of the feet", "frequency": "common"}, {"text": "White, soggy, macerated skin between the toes", "frequency": "common"}, {"text": "Thickened, discolored toenails", "frequency": "sometimes"}, {"text": "Foul foot odor", "frequency": "sometimes"}, {"text": "Small blisters or vesicles on the sole or instep", "frequency": "sometimes"}, {"text": "Painful cracking or fissures of the heel or sole", "frequency": "sometimes"}, {"text": "Red, scaly rash in the groin or on the hands", "frequency": "rare"}], "pertinent_negatives": ["Fever", "Redness spreading rapidly up the leg", "Severe pain out of proportion to the rash", "Purulent drainage or foul-smelling pus", "Numbness or loss of sensation in the feet", "Black or necrotic skin", "Recent antibiotic use", "Known psoriasis or eczema of the feet"]}, "ros": [{"system": "skin", "positives": [{"text": "Itchy, scaly rash between the toes", "frequency": "almost_always"}, {"text": "Peeling or flaking skin on the soles", "frequency": "common"}, {"text": "Small blisters on the foot", "frequency": "sometimes"}, {"text": "Thickened or yellow toenails", "frequency": "sometimes"}], "negatives": ["Rash on the palms or trunk", "Pustules", "Skin ulcers", "Hair loss"], "argues_against": ["Rash involving the palms and soles with nail pitting (psoriasis)", "Honey-colored crusted lesions (impetigo)", "Sharply demarcated plaques with silvery scale"]}, {"system": "musculoskeletal", "positives": [{"text": "Mild soreness when walking", "frequency": "sometimes"}], "negatives": ["Joint swelling", "Joint redness", "Inability to bear weight"], "argues_against": ["Acute monoarthritis of the great toe (gout)", "Cellulitis with severe limb pain"]}, {"system": "constitutional", "positives": [], "negatives": ["Fever", "Chills", "Weight loss", "Night sweats"], "argues_against": ["Systemic infection or cellulitis"]}, {"system": "neurologic", "positives": [], "negatives": ["Numbness or tingling in the feet", "Weakness", "Loss of balance"], "argues_against": ["Diabetic peripheral neuropathy as the primary cause of foot symptoms"]}, {"system": "allergic_immunologic", "positives": [], "negatives": ["New soap, detergent, or shoe material exposure", "Known contact allergy"], "argues_against": ["Contact dermatitis from footwear or topical products"]}], "atypical": [{"population": "children", "how_it_differs": "Often presents with itching and peeling between the toes, but young children may not localize symptoms and instead show fussiness or scratching at the feet; the rash may be mistaken for eczema or diaper rash if it involves the soles.", "missing_classic_features": ["Clear description of itching between the toes"]}, {"population": "older_adults", "how_it_differs": "May have less itching and more dry, cracked, scaly skin on the soles, which can be mistaken for dry skin or eczema; diabetes and poor circulation increase the risk of more extensive or stubborn infection.", "missing_classic_features": ["Prominent itching", "Maceration between the toes"]}, {"population": "diabetes", "how_it_differs": "Athlete's foot can be more extensive, slower to heal, and more likely to lead to bacterial cellulitis or foot ulcers; sensory neuropathy may blunt the itching and pain.", "missing_classic_features": ["Itching as the main symptom"]}, {"population": "immunocompromised", "how_it_differs": "The infection may be more widespread, involve the soles and dorsum extensively, and respond more slowly to topical therapy; risk of secondary bacterial infection is higher.", "missing_classic_features": ["Localized rash limited to the toe web spaces"]}]}, "exam": {"general": {"mild": "Well-appearing, comfortable, no distress; normal gait", "moderate": "Well-appearing; may scratch at the feet or shift weight off the affected foot", "severe": "Well-appearing but uncomfortable; limping or avoiding weight on a fissured foot", "critical": "Ill-appearing with systemic signs (fever, spreading erythema, purulence) suggesting secondary bacterial infection rather than uncomplicated tinea pedis"}, "findings": [{"id": "interdigital-maceration", "region": "skin", "maneuver": "Inspect the web spaces between all toes, spreading the toes apart", "finding": "White, soggy, macerated skin with peeling and fissuring, most often between the fourth and fifth toes", "frequency": "almost_always", "significance": "strongly_supports", "importance": "essential"}, {"id": "interdigital-erythema-scaling", "region": "skin", "maneuver": "Inspect the interdigital skin after drying", "finding": "Erythema with fine scaling and a slightly raised, advancing edge", "frequency": "common", "significance": "supports", "importance": "important"}, {"id": "plantar-scaling", "region": "skin", "maneuver": "Inspect the soles and heels", "finding": "Diffuse dry scaling, sometimes in a moccasin-like distribution over the sole and heel", "frequency": "common", "significance": "supports", "importance": "important"}, {"id": "plantar-vesicles", "region": "skin", "maneuver": "Inspect the instep and sole", "finding": "Small grouped vesicles or blisters", "frequency": "sometimes", "significance": "supports", "importance": "important"}, {"id": "fissures", "region": "skin", "maneuver": "Inspect the heel and interdigital spaces", "finding": "Painful cracks or fissures of the skin", "frequency": "sometimes", "min_severity": "moderate", "significance": "supports", "importance": "important"}, {"id": "dermatophyte-odor", "region": "skin", "maneuver": "Note any odor when removing socks or examining the feet", "finding": "Musty or foul foot odor", "frequency": "sometimes", "significance": "supports", "importance": "optional"}, {"id": "onychomycosis", "region": "extremities", "maneuver": "Inspect all toenails", "finding": "Thickened, yellow-brown, crumbling, or distally separated nails", "frequency": "sometimes", "significance": "supports", "importance": "important"}, {"id": "dorsal-extension", "region": "skin", "maneuver": "Inspect the dorsum of the foot", "finding": "Scaling or erythema extending onto the top of the foot", "frequency": "sometimes", "significance": "supports", "importance": "optional"}, {"id": "no-pustules", "region": "skin", "maneuver": "Inspect the rash for pustules or honey-colored crust", "finding": "No pustules or honey-colored crust", "frequency": "almost_always", "significance": "argues_against", "importance": "important"}, {"id": "no-cellulitis", "region": "extremities", "maneuver": "Palpate the leg and foot for warmth, tenderness, and spreading erythema", "finding": "No warmth, tenderness, or erythema extending up the leg", "frequency": "almost_always", "significance": "argues_against", "importance": "essential"}, {"id": "no-ulcer", "region": "skin", "maneuver": "Inspect the sole and between the toes for breaks in the skin", "finding": "No ulcer or full-thickness skin defect", "frequency": "almost_always", "significance": "argues_against", "importance": "important"}, {"id": "no-neuropathy", "region": "neuro", "maneuver": "Test sensation with monofilament or light touch, especially if diabetes is present", "finding": "Intact sensation in the feet", "frequency": "almost_always", "significance": "neutral", "importance": "important"}, {"id": "no-joint-swelling", "region": "musculoskeletal", "maneuver": "Inspect and palpate the joints of the foot and ankle", "finding": "No joint swelling, warmth, or redness", "frequency": "almost_always", "significance": "argues_against", "importance": "optional"}, {"id": "no-palmoplantar-pustulosis", "region": "skin", "maneuver": "Inspect the palms and soles", "finding": "No sterile pustules or sharply demarcated silvery plaques on the palms and soles", "frequency": "almost_always", "significance": "argues_against", "importance": "optional"}]}, "vitals": {}, "labs": [], "imaging": [], "workup": {"initial": [{"test": "Potassium hydroxide mount", "why": "First-line bedside test: scraped scale from the active edge or macerated web space shows branching septate hyphae, confirming a dermatophyte infection"}, {"test": "Fungal culture", "why": "Identifies the species when the diagnosis is uncertain or the rash fails topical therapy", "only_if": "KOH is negative but tinea pedis is still suspected, or the infection is not responding to treatment"}], "confirmatory": [], "supporting": [{"test": "Wood lamp examination", "why": "Helps distinguish dermatophyte infection from erythrasma or other causes of interdigital scaling", "only_if": "the diagnosis is unclear after KOH testing"}], "not_indicated": [{"test": "cbc", "why": "No role in a localized superficial fungal infection; a normal white count is expected"}, {"test": "crp", "why": "Inflammatory markers are not useful for tinea pedis"}, {"test": "esr", "why": "Not helpful in superficial fungal skin infection"}, {"test": "glucose", "why": "Not needed to diagnose athlete's foot; check only if diabetes is suspected or already known"}, {"test": "a1c", "why": "Not part of the workup for athlete's foot"}, {"test": "Bacterial culture wound", "why": "Only if secondary bacterial infection is suspected; not routine for uncomplicated tinea pedis"}, {"test": "Xray foot", "why": "No bony abnormality in athlete's foot; imaging does not help"}, {"test": "Mri foot", "why": "Not indicated for a superficial skin infection"}], "decision_points": ["Confirm the diagnosis with KOH microscopy before starting systemic therapy or when the rash does not respond to topical antifungals", "Look for onychomycosis and treat it, since infected nails are a reservoir for recurrent tinea pedis", "In diabetes or immunosuppression, examine carefully for fissures, ulcers, and secondary bacterial infection"], "criteria": [], "scores": []}, "differential": [{"name": "Cellulitis", "slug": "cellulitis", "why_considered": "Both cause a red, warm, painful foot; cellulitis can complicate or mimic tinea pedis.", "must_not_miss": true, "trigger": "Rapidly spreading redness, fever, or systemic symptoms", "discriminators": {"history": ["Acute onset over hours to days", "Fever and chills", "Pain out of proportion to skin findings"], "exam": ["Diffuse erythema, warmth, and tenderness without scaling or maceration", "Lymphangitic streaking", "No interdigital maceration"], "labs": ["Leukocytosis", "Elevated inflammatory markers (CRP, ESR)"], "imaging": ["Not routinely needed; consider ultrasound if abscess suspected"]}}, {"name": "Contact dermatitis", "slug": "contact-dermatitis", "why_considered": "Itchy, red, scaly rash on the feet, often triggered by shoes or topical products.", "must_not_miss": false, "discriminators": {"history": ["Exposure to new shoes, socks, or topical agents", "Itching and burning without a musty odor", "No improvement with antifungals"], "exam": ["Erythema and scaling on the dorsum or areas of contact, often sparing the web spaces", "Sharp demarcation at the shoe line", "No maceration between toes"], "labs": ["KOH negative"], "imaging": []}}, {"name": "Psoriasis", "slug": "psoriasis", "why_considered": "Scaly plaques on the soles and between toes can resemble tinea pedis.", "must_not_miss": false, "discriminators": {"history": ["Chronic, persistent rash", "Personal or family history of psoriasis", "Nail pitting or separation"], "exam": ["Well-demarcated plaques with silvery scale, often on soles and palms", "Nail changes (pitting, oil spots, onycholysis)", "No central clearing or advancing border"], "labs": ["KOH negative"], "imaging": []}}, {"name": "Erythrasma", "slug": "erythrasma", "why_considered": "Interdigital scaling and maceration caused by Corynebacterium minutissimum.", "must_not_miss": false, "discriminators": {"history": ["Mild itching or asymptomatic", "Often in toe web spaces", "May have similar rash in groin or axillae"], "exam": ["Sharply demarcated, brownish-red, scaly patches", "Wood's lamp shows coral-red fluorescence", "KOH negative"], "labs": ["Wood's lamp examination", "Bacterial culture if needed"], "imaging": []}}, {"name": "Pitted keratolysis", "slug": "pitted-keratolysis", "why_considered": "Causes small pits and maceration on the soles, often with odor.", "must_not_miss": false, "discriminators": {"history": ["Hyperhidrosis", "Foul odor", "Mild or no itching"], "exam": ["Multiple small punched-out pits on the soles, especially weight-bearing areas", "No interdigital maceration", "KOH negative"], "labs": ["Clinical diagnosis; KOH negative"], "imaging": []}}, {"name": "Dyshidrotic eczema", "slug": "dyshidrotic-eczema", "why_considered": "Vesicular rash on the soles and palms that can be itchy.", "must_not_miss": false, "discriminators": {"history": ["Recurrent episodes of itchy vesicles", "Often associated with atopy or stress", "No response to antifungals"], "exam": ["Deep-seated vesicles on the instep and palms", "Scaling and fissures after vesicles resolve", "No interdigital maceration"], "labs": ["KOH negative"], "imaging": []}}], "course": {"severity": {"mild": "Mild itching and scaling limited to the toe web spaces; no fissures or secondary infection.", "moderate": "More extensive scaling, maceration, and fissures involving the sole or multiple web spaces; itching interferes with sleep.", "severe": "Extensive involvement of the sole and dorsum, painful fissures, and possible secondary bacterial infection; may require systemic antifungal therapy."}, "red_flags": [{"finding": "Rapidly spreading redness, warmth, and swelling of the foot or leg", "meaning": "Suggests bacterial cellulitis, which requires prompt antibiotic treatment."}, {"finding": "Fever, chills, or systemic symptoms", "meaning": "Indicates possible systemic infection or severe secondary bacterial infection."}, {"finding": "Purulent drainage or foul-smelling pus", "meaning": "Suggests secondary bacterial infection or abscess."}, {"finding": "Severe pain out of proportion to skin findings", "meaning": "May indicate deeper infection such as abscess or necrotizing fasciitis."}, {"finding": "Black or necrotic skin", "meaning": "Suggests necrotizing infection or severe vascular compromise; emergency."}, {"finding": "Numbness or loss of sensation in the feet", "meaning": "May indicate peripheral neuropathy, increasing risk of unnoticed injury and infection."}], "complications": [{"name": "Secondary bacterial infection (cellulitis)", "timing": "any", "seriousness": "serious", "frequency": "sometimes", "clues": ["Increasing redness, warmth, and pain", "Fever", "Purulent drainage"]}, {"name": "Onychomycosis", "timing": "late", "seriousness": "minor", "frequency": "sometimes", "clues": ["Thickened, discolored, crumbling toenails", "Persistent tinea pedis despite treatment"]}, {"name": "Chronic fissures and pain", "timing": "late", "seriousness": "minor", "frequency": "sometimes", "clues": ["Persistent heel or interdigital fissures", "Pain with walking"]}, {"name": "Recurrence", "timing": "late", "seriousness": "minor", "frequency": "common", "clues": ["History of previous episodes", "Untreated onychomycosis or continued exposure to damp environments"]}], "special_populations": [{"population": "children", "differences": "May present with itching and peeling between toes, but young children may not localize symptoms; rash may be mistaken for eczema."}, {"population": "older_adults", "differences": "Less itching and more dry, cracked, scaly skin on the soles; may be mistaken for dry skin or eczema; diabetes and poor circulation increase risk of complications."}, {"population": "diabetes", "differences": "More extensive, slower to heal, and higher risk of bacterial cellulitis or foot ulcers; sensory neuropathy may blunt itching and pain."}, {"population": "immunocompromised", "differences": "Infection may be more widespread, involve soles and dorsum extensively, respond more slowly to topical therapy, and have higher risk of secondary bacterial infection."}]}, "teaching": {"key_questions": [{"question": "Where exactly on your feet did the rash start, and where is it now?", "category": "hpi", "importance": "essential", "looking_for": "Starts between the toes, especially the fourth and fifth web space, then may spread to the sole or top of the foot"}, {"question": "How long has it been there, and is it getting better or worse?", "category": "hpi", "importance": "essential", "looking_for": "Gradual onset over days to weeks; may wax and wane or recur over months"}, {"question": "What does the skin look like and feel like?", "category": "hpi", "importance": "essential", "looking_for": "Itchy, peeling, cracked, scaly, or white and soggy skin between the toes"}, {"question": "Does it itch or burn, and when is it worst?", "category": "hpi", "importance": "important", "looking_for": "Itching or burning, often worse at night or after removing shoes and socks"}, {"question": "What makes it better or worse?", "category": "hpi", "importance": "important", "looking_for": "Worse with sweating, closed shoes, warm humid weather; better with dry feet, sandals, or antifungal cream"}, {"question": "Do you walk barefoot in locker rooms, public showers, or around pools?", "category": "social", "importance": "essential", "looking_for": "Exposure to damp communal floors, a classic risk factor"}, {"question": "Do your feet sweat a lot, or do you wear closed shoes all day?", "category": "hpi", "importance": "important", "looking_for": "Hyperhidrosis or occlusive footwear"}, {"question": "Does anyone at home have the same foot rash or thick, discolored toenails?", "category": "family", "importance": "important", "looking_for": "Household member with tinea pedis or onychomycosis; shared footwear or towels"}, {"question": "Have you had this before, and did anything treat it?", "category": "pmh", "importance": "important", "looking_for": "Prior episodes or partial response to over-the-counter antifungals"}, {"question": "Do you have diabetes, poor circulation, or a weakened immune system?", "category": "pmh", "importance": "essential", "looking_for": "Diabetes, peripheral arterial disease, venous insufficiency, or immunosuppression; raises risk of complications"}, {"question": "Are you taking any medicines that suppress the immune system, like prednisone or a biologic?", "category": "medications", "importance": "important", "looking_for": "Corticosteroids, tacrolimus, cyclosporine, methotrexate, or TNF inhibitors"}, {"question": "Have you used any creams, powders, or home remedies on it?", "category": "medications", "importance": "optional", "looking_for": "Antifungal use, steroid creams, or other topical products that may change the appearance"}, {"question": "Have you had a fever, chills, or redness spreading up your leg?", "category": "red_flag", "importance": "essential", "looking_for": "Absent in uncomplicated tinea pedis; present suggests cellulitis or systemic infection"}, {"question": "Is the pain severe, or is there pus or a foul-smelling discharge?", "category": "red_flag", "importance": "essential", "looking_for": "Absent; present suggests secondary bacterial infection or deeper infection"}, {"question": "Any numbness, tingling, or loss of feeling in your feet?", "category": "ros", "importance": "important", "looking_for": "Absent; present suggests peripheral neuropathy and higher risk of unnoticed injury"}, {"question": "Any rash in your groin, on your hands, or elsewhere?", "category": "associated", "importance": "optional", "looking_for": "Tinea cruris or tinea manuum, which often accompany tinea pedis"}], "accepted_names": ["Athlete's foot", "Tinea pedis", "Dermatophyte infection of the foot", "Foot fungus", "Fungal foot infection"], "reasoning_points": ["Itchy, scaly, peeling rash that begins in the toe web spaces, especially between the fourth and fifth toes", "Maceration, fissuring, or a moccasin-like pattern of scaling on the sole", "Exposure to damp communal floors such as locker rooms, showers, or pool decks", "Risk factors such as hyperhidrosis,