evere when the rate is very fast or when heart failure or low blood pressure develops", "timing": "Episodes can start at any time, often at rest or at night; exercise and alcohol can bring them on", "aggravating": ["Alcohol", "Caffeine", "Exercise or exertion", "Stress", "Dehydration or acute illness"], "relieving": ["Resting and sitting down", "Episodes may stop on their own", "Rate-controlling medication"], "associated_symptoms": [{"text": "Fatigue or low energy", "frequency": "common"}, {"text": "Shortness of breath with activity", "frequency": "common"}, {"text": "Feeling lightheaded or dizzy", "frequency": "sometimes"}, {"text": "Shortness of breath when lying flat", "frequency": "sometimes"}, {"text": "Chest discomfort or pressure", "frequency": "sometimes"}, {"text": "Swelling in the ankles or legs", "frequency": "sometimes"}, {"text": "Waking up at night short of breath", "frequency": "sometimes"}, {"text": "Fainting", "frequency": "rare"}, {"text": "Sudden weakness or numbness on one side, trouble speaking, or vision loss (from a clot causing a stroke)", "frequency": "rare"}], "pertinent_negatives": ["Crushing chest pain that radiates to the arm or jaw and comes on with exertion", "Fever", "Coughing up blood", "Recent long car ride, flight, or leg surgery with one-sided leg swelling", "Sudden sharp chest pain that worsens with a deep breath", "Known prior heart attack with the same pain", "Vomiting or diarrhea causing dehydration"]}, "ros": [{"system": "constitutional", "positives": [{"text": "Tiredness or low energy", "frequency": "common"}, {"text": "Poor exercise tolerance", "frequency": "common"}], "negatives": ["Fever", "Unintentional weight loss", "Night sweats"]}, {"system": "cardiovascular", "positives": [{"text": "Palpitations or fluttering in the chest", "frequency": "common"}, {"text": "Irregular or racing pulse", "frequency": "common"}, {"text": "Chest discomfort", "frequency": "sometimes"}, {"text": "Swelling in the legs or ankles", "frequency"