lls"]}], "special_populations": [{"population": "children", "differences": "Back pain in children is uncommon and more often has an identifiable cause such as spondylolysis, infection, or tumor; children may present with refusal to walk or irritability rather than a clear pain description."}, {"population": "older_adults", "differences": "More likely to have degenerative changes, spinal stenosis, or compression fracture; pain may be less activity-related and more constant, and serious causes are more common."}, {"population": "pregnancy", "differences": "Pain is often in the lumbosacral region or posterior pelvis, worse with prolonged standing or walking, and may be accompanied by pelvic girdle pain; red flags still require the same evaluation."}, {"population": "obesity", "differences": "Higher mechanical load and deconditioning can make pain more persistent and less responsive to activity; weight loss is often part of management."}]}, "teaching": {"key_questions": [{"question": "Where is the pain, and does it stay in your back or travel anywhere?", "category": "hpi", "importance": "essential", "looking_for": "Lumbosacral location; radiation into the buttock, posterior thigh, or below the knee suggests radiculopathy"}, {"question": "When did it start, and was there a specific movement, lift, or injury?", "category": "hpi", "importance": "essential", "looking_for": "Gradual or sudden onset after activity or minor trauma; no trauma suggests mechanical or other cause"}, {"question": "How long has it been going on?", "category": "hpi", "importance": "essential", "looking_for": "Acute (days to weeks) versus chronic (more than three months)"}, {"question": "What makes it better or worse?", "category": "hpi", "importance": "important", "looking_for": "Worse with bending, lifting, prolonged sitting or standing; better with rest or position change"}, {"question": "Does the pain wake you from sleep or occur at night?", "category": "red_flag", "importance": "essential", "looking_for": "Night pain that wakes from sleep suggests infection or malignancy"}, {"question": "Have you had any loss of bladder or bowel control, or trouble urinating?", "category": "red_flag", "importance": "essential", "looking_for": "Urinary retention or incontinence suggests cauda equina syndrome"}, {"question": "Any numbness or tingling in the groin, inner thighs, or buttocks?", "category": "red_flag", "importance": "essential", "looking_for": "Saddle anesthesia suggests cauda equina syndrome"}, {"question": "Any weakness in your legs, or has your foot been dragging?", "category": "red_flag", "importance": "essential", "looking_for": "Progressive or severe leg weakness suggests nerve root or cord compression"}, {"question": "Have you had any fever, chills, or night sweats?", "category": "associated", "importance": "essential", "looking_for": "Fever or chills suggest spinal infection"}, {"question": "Have you lost weight without trying?", "category": "associated", "importance": "essential", "looking_for": "Unintentional weight loss suggests malignancy"}, {"question": "Have you ever been told you have cancer?", "category": "pmh", "importance": "essential", "looking_for": "History of cancer raises concern for spinal metastasis"}, {"question": "Have you ever used intravenous drugs, or had a recent infection or spinal procedure?", "category": "pmh", "importance": "important", "looking_for": "Risk factors for spinal infection"}, {"question": "Do you take corticosteroids regularly, or have you been told you have osteoporosis?", "category": "medications", "importance": "important", "looking_for": "Increased risk of vertebral compression fracture"}, {"question": "Have you had a fall or other injury to your back?", "category": "hpi", "importance": "important", "looking_for": "Trauma raises concern for fracture"}, {"question": "What do you do for work, and does it involve heavy lifting or prolonged sitting?", "category": "social", "importance": "important", "looking_for": "Occupational strain and job control influence risk and recovery"}, {"question": "Do you smoke, and how much alcohol do you drink?", "category": "social", "importance": "optional", "looking_for": "Smoking and alcohol use affect bone health and recovery"}, {"question": "Does anyone in your family have back problems or arthritis of the spine?", "category": "family", "importance": "optional", "looking_for": "Family history of back pain or ankylosing spondylitis"}, {"question": "Any burning or shooting pain in a band around your chest or back, or a rash?", "category": "associated", "importance": "optional", "looking_for": "Dermatomal pain preceding a rash suggests herpes zoster"}, {"question": "Any trouble with urination, blood in the urine, or flank pain?", "category": "ros", "importance": "important", "looking_for": "Urinary symptoms suggest a renal source"}, {"question": "Any abdominal pain, nausea, or vomiting?", "category": "ros", "importance": "optional", "looking_for": "Abdominal symptoms suggest pancreatitis or another abdominal source"}, {"question": "Could you be pregnant? When was your last period?", "category": "obstetric", "importance": "essential", "looking_for": "Pregnancy must be excluded before imaging"}], "accepted_names": ["Back pain", "Backache", "Lumbago", "Low back pain", "Mechanical back pain"], "reasoning_points": ["Pain is in the lumbosacral region, worse with movement and better with rest, consistent with a mechanical pattern", "No red flags: no saddle anesthesia, no bowel or bladder dysfunction, no fever, no weight loss, no cancer history, no significant trauma", "No progressive or severe leg weakness and no foot drop", "Neurologic exam is intact: normal strength, sensation, reflexes, and gait", "No focal spinal tenderness or point tenderness over a spinous process", "No costovertebral angle tenderness and no abdominal tenderness or pulsatile mass", "Pregnancy excluded before any imaging", "Imaging is not indicated in uncomplicated mechanical back pain without red flags"], "difficulty": {"easy": ["Young or middle-aged adult with acute onset after lifting", "Pain limited to the lower back without radiation", "Paraspinal tenderness and pain-limited flexion", "No red flags and a normal neurologic exam"], "medium": ["Radicular pain radiating below the knee with a positive straight leg raise", "Older adult with new back pain but no red flags", "Pregnancy with lumbosacral and pelvic girdle pain", "Patient with obesity and persistent pain despite conservative care"], "hard": ["Older adult with a compression fracture after minor trauma or corticosteroid use", "Fever, night pain, and leukocytosis suggesting spinal infection", "History of cancer with night pain and weight loss suggesting metastasis", "Saddle anesthesia or urinary retention suggesting cauda equina syndrome", "Sudden severe tearing mid-back pain with a pulsatile abdominal mass suggesting aortic aneurysm"]}}}$rounds_kb$::jsonb)
